def search(api_key, q, limit=None, **_extra):
    import json, os, datetime, uuid, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0452000" if __import__("os").path.isdir("./environment_mix/0452000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if not isinstance(dt, datetime.datetime):
            dt = _now()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _month_bounds(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        start = dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
        if start.month == 12:
            nxt = start.replace(year=start.year + 1, month=1)
        else:
            nxt = start.replace(month=start.month + 1)
        return start, nxt

    def _plan_default_quota(plan):
        # Conservative defaults; if workspace/key doesn't set a quota, plans still have an implicit limit.
        # (Store may override via monthly_request_quota / monthly_request_quota_override.)
        return {
            "free": 1000,
            "pro": 10000,
            "business": 50000,
            "enterprise": 200000,
        }.get(plan, 1000)

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    # Validate inputs (relax q type per audit: accept non-string and coerce to string)
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("UNAUTHORIZED", "api_key is missing, invalid, or revoked")
    if q is None:
        return _err("VALIDATION_ERROR", "q is required")
    if isinstance(q, (dict, list, tuple, set)):
        return _err("VALIDATION_ERROR", "q must be a string or scalar convertible to string")
    q_str = q if isinstance(q, str) else str(q)
    if limit is not None:
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit < 1 or limit > 50:
            return _err("VALIDATION_ERROR", "limit must be between 1 and 50")

    # Load collections
    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    search_queries = _load("search_queries.json")
    search_responses = _load("search_responses.json")
    usage_ledger = _load("usage_ledger.json")

    # Build indices
    ws_by_id = {w.get("id"): w for w in workspaces if isinstance(w, dict) and isinstance(w.get("id"), str)}
    keys = [k for k in api_keys if isinstance(k, dict)]

    # Authenticate: api_key matches client-visible value or id; never key_hash.
    key_candidates = []
    for k in keys:
        if api_key == k.get("id"):
            key_candidates.append(k)
    if not key_candidates:
        for k in keys:
            for field in ("api_key", "key", "secret", "token", "value"):
                if api_key == k.get(field):
                    key_candidates.append(k)
                    break

    authed_key = None
    authed_ws = None
    for k in key_candidates:
        if k.get("status") != "active":
            continue
        ws = ws_by_id.get(k.get("workspace_id"))
        if not ws or ws.get("status") != "active":
            continue
        allowed = k.get("allowed_tools")
        if isinstance(allowed, list) and allowed and ("search" not in allowed):
            continue
        authed_key = k
        authed_ws = ws
        break

    if not authed_key or not authed_ws:
        return _err("UNAUTHORIZED", "No active API key/workspace combination found for this request")

    now = _now()

    # Data retention enforcement (best-effort; does not error the call)
    try:
        retention_days = authed_ws.get("data_retention_days")
        if isinstance(retention_days, int) and retention_days >= 0:
            cutoff = now - datetime.timedelta(days=retention_days)

            # Purge old search_responses payloads and mark status='purged'
            changed_responses = False
            for rsp in search_responses:
                if not isinstance(rsp, dict):
                    continue
                created = _parse_dt(rsp.get("created_at")) or _parse_dt(rsp.get("updated_at"))
                if created and created < cutoff and rsp.get("status") != "purged":
                    # only purge payloads; keep row
                    rsp["status"] = "purged"
                    rsp["response_json"] = None
                    rsp["response_text"] = None
                    rsp["updated_at"] = _iso(now)
                    changed_responses = True
            if changed_responses:
                _save("search_responses.json", search_responses)

            # Remove old usage/search_queries beyond retention (allowed by rules)
            def _keep_recent(row):
                if not isinstance(row, dict):
                    return False
                created = _parse_dt(row.get("created_at")) or _parse_dt(row.get("occurred_at"))
                return not (created and created < cutoff)

            new_usage = [u for u in usage_ledger if _keep_recent(u)]
            if len(new_usage) != len(usage_ledger):
                usage_ledger = new_usage
                _save("usage_ledger.json", usage_ledger)

            new_queries = []
            removed_query_ids = set()
            for sq in search_queries:
                if not isinstance(sq, dict):
                    continue
                created = _parse_dt(sq.get("created_at"))
                if created and created < cutoff:
                    removed_query_ids.add(sq.get("id"))
                else:
                    new_queries.append(sq)
            if removed_query_ids:
                search_queries = new_queries
                _save("search_queries.json", search_queries)

                # Cascade delete responses for removed queries
                new_resps = [r for r in search_responses if not (isinstance(r, dict) and r.get("query_id") in removed_query_ids)]
                if len(new_resps) != len(search_responses):
                    search_responses = new_resps
                    _save("search_responses.json", search_responses)
    except Exception:
        # unexpected programming/runtime errors should surface as error object, not crash
        return _err("INTERNAL_ERROR", "Internal error during retention maintenance")

    # Quota enforcement: count search_request events in current calendar month
    start, end = _month_bounds(now)
    def _in_month(u):
        if not isinstance(u, dict):
            return False
        if u.get("event_type") != "search_request":
            return False
        if u.get("workspace_id") != authed_ws.get("id"):
            return False
        if u.get("api_key_id") != authed_key.get("id"):
            return False
        t = _parse_dt(u.get("occurred_at")) or _parse_dt(u.get("created_at"))
        return bool(t and (start <= t < end))

    month_requests = sum(1 for u in usage_ledger if _in_month(u))

    override = authed_key.get("monthly_request_quota_override")
    ws_quota = authed_ws.get("monthly_request_quota")
    plan_quota = _plan_default_quota(authed_ws.get("plan"))
    effective_quota = None
    if isinstance(override, int):
        effective_quota = override
    elif isinstance(ws_quota, int):
        effective_quota = ws_quota
    else:
        effective_quota = plan_quota

    if isinstance(effective_quota, int) and effective_quota >= 0 and month_requests >= effective_quota:
        # Record failed invocation (audit + usage) for observability
        qid = _gen_id("kgi_qry")
        query_row = {
            "id": qid,
            "workspace_id": authed_ws.get("id"),
            "api_key_id": authed_key.get("id"),
            "status": "failed",
            "tool_name": "search",
            "input": {},
            "request_ip": None,
            "user_agent": None,
            "error_code": "quota_exceeded",
            "error_message": "Monthly request quota exceeded for this API key.",
            "http_status": 429,
            "duration_ms": int((time.time() - _t0) * 1000),
            "created_at": _iso(now),
            "updated_at": _iso(now),
            "completed_at": _iso(now),
        }
        search_queries.append(query_row)
        usage_ledger.append({
            "id": _gen_id("kgi_use"),
            "workspace_id": authed_ws.get("id"),
            "api_key_id": authed_key.get("id"),
            "query_id": qid,
            "event_type": "search_request",
            "units": 1,
            "occurred_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        usage_ledger.append({
            "id": _gen_id("kgi_use"),
            "workspace_id": authed_ws.get("id"),
            "api_key_id": authed_key.get("id"),
            "query_id": qid,
            "event_type": "search_failure",
            "units": 0,
            "occurred_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        authed_key["last_used_at"] = _iso(now)
        authed_key["updated_at"] = _iso(now)
        _save("search_queries.json", search_queries)
        _save("usage_ledger.json", usage_ledger)
        _save("api_keys.json", api_keys)
        return _err("QUOTA_EXCEEDED", "Monthly request quota exceeded for this API key/workspace", query_id=qid, http_status=429)

    # Create search_queries row (queued->running->succeeded)
    qid = _gen_id("kgi_qry")
    created_at = _iso(now)
    query_row = {
        "id": qid,
        "workspace_id": authed_ws.get("id"),
        "api_key_id": authed_key.get("id"),
        "status": "queued",
        "tool_name": "search",
        "input": {},  # MCP surface requires empty object
        "request_ip": None,
        "user_agent": None,
        "error_code": None,
        "error_message": None,
        "http_status": None,
        "duration_ms": None,
        "created_at": created_at,
        "updated_at": created_at,
        "completed_at": None,
    }
    search_queries.append(query_row)

    # Initial usage_ledger row: search_request
    usage_ledger.append({
        "id": _gen_id("kgi_use"),
        "workspace_id": authed_ws.get("id"),
        "api_key_id": authed_key.get("id"),
        "query_id": qid,
        "event_type": "search_request",
        "units": 1,
        "occurred_at": _iso(now),
        "created_at": _iso(now),
        "updated_at": _iso(now),
    })

    # Mark running
    query_row["status"] = "running"
    query_row["updated_at"] = _iso(_now())

    # Produce deterministic, stored response payload (offline)
    lim = limit if isinstance(limit, int) else 10
    results = []
    for i in range(lim):
        rank = i + 1
        results.append({
            "title": f"Result {rank} for {q_str}",
            "url": f"https://example.com/search?q={q_str}&r={rank}",
            "snippet": f"Synthetic offline result {rank} generated for query '{q_str}'.",
            "rank": rank,
        })
    payload = {
        "query": q_str,
        "limit": lim,
        "results": results,
        "provider": "offline-synthetic",
    }
    payload_text = "\n".join([f"{r['rank']}. {r['title']} - {r['url']}" for r in results])

    # Persist one search_responses row (unique query_id)
    rsp_id = _gen_id("kgi_rsp")
    rsp_row = {
        "id": rsp_id,
        "query_id": qid,
        "status": "stored",
        "upstream_provider": "offline-synthetic",
        "result_count": len(results),
        "response_json": payload,
        "response_text": payload_text,
        "bytes": len(json.dumps(payload, ensure_ascii=False).encode("utf-8")),
        "created_at": _iso(_now()),
        "updated_at": _iso(_now()),
    }
    # Ensure uniqueness by query_id
    for existing in search_responses:
        if isinstance(existing, dict) and existing.get("query_id") == qid:
            return _err("CONFLICT", "Response already exists for this query_id", query_id=qid)
    search_responses.append(rsp_row)

    # Mark query succeeded + usage success
    done = _now()
    query_row["status"] = "succeeded"
    query_row["http_status"] = 200
    query_row["duration_ms"] = int((time.time() - _t0) * 1000)
    query_row["updated_at"] = _iso(done)
    query_row["completed_at"] = _iso(done)

    usage_ledger.append({
        "id": _gen_id("kgi_use"),
        "workspace_id": authed_ws.get("id"),
        "api_key_id": authed_key.get("id"),
        "query_id": qid,
        "event_type": "search_success",
        "units": 0,
        "occurred_at": _iso(done),
        "created_at": _iso(done),
        "updated_at": _iso(done),
    })

    # Update key usage timestamp
    authed_key["last_used_at"] = _iso(done)
    authed_key["updated_at"] = _iso(done)

    # Persist mutations
    _save("search_queries.json", search_queries)
    _save("search_responses.json", search_responses)
    _save("usage_ledger.json", usage_ledger)
    _save("api_keys.json", api_keys)

    return {
        "query_id": qid,
        "response_id": rsp_id,
        "data": payload,
        "meta": {
            "workspace_id": authed_ws.get("id"),
            "api_key_id": authed_key.get("id"),
            "limit": lim,
            "result_count": len(results),
            "stored": True,
        },
    }

def get_me(api_key, **_extra):
    import json, os, datetime, time, uuid, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0452000" if __import__("os").path.isdir("./environment_mix/0452000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _month_bounds(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        start = dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
        if start.month == 12:
            next_m = start.replace(year=start.year + 1, month=1)
        else:
            next_m = start.replace(month=start.month + 1)
        return start, next_m

    def _hash_key(s):
        if not isinstance(s, str):
            return None
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    if not isinstance(api_key, str) or not api_key.strip():
        return _err("UNAUTHORIZED", "api_key is missing or invalid")

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    usage_ledger = _load("usage_ledger.json")

    ws_by_id = {w.get("id"): w for w in workspaces if isinstance(w, dict)}
    key_hash = _hash_key(api_key)

    authed_key = None
    authed_ws = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("status") != "active":
            continue
        wid = k.get("workspace_id")
        ws = ws_by_id.get(wid)
        if not ws or ws.get("status") != "active":
            continue
        if api_key == k.get("id") or api_key == k.get("key_hash") or (key_hash and key_hash == k.get("key_hash")):
            authed_key = k
            authed_ws = ws
            break

    if not authed_key or not authed_ws:
        return _err("UNAUTHORIZED", "api_key is missing/invalid/revoked or workspace is not active")

    now_dt = datetime.datetime.now(datetime.timezone.utc)
    m0, m1 = _month_bounds(now_dt)

    def _in_month(row):
        dt = _parse_dt(row.get("occurred_at"))
        if not dt:
            return False
        dt = dt.astimezone(datetime.timezone.utc)
        return (dt >= m0 and dt < m1)

    used = 0
    for ev in usage_ledger:
        if not isinstance(ev, dict):
            continue
        if ev.get("event_type") != "search_request":
            continue
        if ev.get("workspace_id") != authed_ws.get("id"):
            continue
        if ev.get("api_key_id") != authed_key.get("id"):
            continue
        if _in_month(ev):
            units = ev.get("units")
            if isinstance(units, int) and units >= 0:
                used += units
            else:
                used += 1

    plan_defaults = {
        "free": 1000,
        "pro": 10000,
        "business": 100000,
        "enterprise": None,
    }
    plan = authed_ws.get("plan")
    plan_quota = plan_defaults.get(plan, 1000)
    ws_quota = authed_ws.get("monthly_request_quota")
    key_quota = authed_key.get("monthly_request_quota_override")
    effective_quota = key_quota if isinstance(key_quota, int) else (ws_quota if isinstance(ws_quota, int) else plan_quota)

    ts = _now()
    authed_key["last_used_at"] = ts
    authed_key["updated_at"] = ts
    _save("api_keys.json", api_keys)

    return {
        "data": {
            "workspace": {
                "id": authed_ws.get("id"),
                "name": authed_ws.get("name"),
                "status": authed_ws.get("status"),
                "plan": authed_ws.get("plan"),
                "data_retention_days": authed_ws.get("data_retention_days"),
                "monthly_request_quota": authed_ws.get("monthly_request_quota"),
                "created_at": authed_ws.get("created_at"),
                "updated_at": authed_ws.get("updated_at"),
            },
            "api_key": {
                "id": authed_key.get("id"),
                "name": authed_key.get("name"),
                "status": authed_key.get("status"),
                "allowed_tools": authed_key.get("allowed_tools"),
                "monthly_request_quota_override": authed_key.get("monthly_request_quota_override"),
                "last_used_at": authed_key.get("last_used_at"),
                "created_at": authed_key.get("created_at"),
                "updated_at": authed_key.get("updated_at"),
            },
            "quota": {
                "effective_monthly_request_quota": effective_quota,
                "current_month_search_requests_used": used,
                "month_start": m0.isoformat(),
                "month_end": m1.isoformat(),
            },
        },
        "meta": {
            "duration_ms": int((time.time() - _t0) * 1000),
        },
    }

def list_search_queries(api_key, page=None, per_page=None, status=None, api_key_id=None, tool_name=None, created_after=None, created_before=None, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0452000" if __import__("os").path.isdir("./environment_mix/0452000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _hash_key(s):
        if not isinstance(s, str):
            return None
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    if not isinstance(api_key, str) or not api_key.strip():
        return _err("UNAUTHORIZED", "api_key is missing or invalid")

    if page is None:
        page = 1
    if per_page is None:
        per_page = 50
    if not isinstance(page, int) or page < 1:
        return _err("VALIDATION_ERROR", "page must be an integer >= 1")
    if not isinstance(per_page, int) or per_page < 1 or per_page > 100:
        return _err("VALIDATION_ERROR", "per_page must be an integer between 1 and 100")

    if status is not None:
        allowed = {"queued", "running", "succeeded", "failed", "cancelled"}
        if not isinstance(status, str) or status not in allowed:
            return _err("VALIDATION_ERROR", "status is invalid")

    if api_key_id is not None and (not isinstance(api_key_id, str) or not api_key_id.strip()):
        return _err("VALIDATION_ERROR", "api_key_id must be a non-empty string")
    if tool_name is not None and (not isinstance(tool_name, str) or not tool_name.strip()):
        return _err("VALIDATION_ERROR", "tool_name must be a non-empty string")

    ca = _parse_dt(created_after)
    if created_after is not None and ca is None:
        return _err("VALIDATION_ERROR", "created_after must be RFC3339 date-time")
    cb = _parse_dt(created_before)
    if created_before is not None and cb is None:
        return _err("VALIDATION_ERROR", "created_before must be RFC3339 date-time")
    if ca and cb and ca > cb:
        return _err("VALIDATION_ERROR", "created_after must be <= created_before")

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    search_queries = _load("search_queries.json")

    ws_by_id = {w.get("id"): w for w in workspaces if isinstance(w, dict)}
    key_hash = _hash_key(api_key)

    authed_key = None
    authed_ws = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("status") != "active":
            continue
        wid = k.get("workspace_id")
        ws = ws_by_id.get(wid)
        if not ws or ws.get("status") != "active":
            continue
        if api_key == k.get("id") or api_key == k.get("key_hash") or (key_hash and key_hash == k.get("key_hash")):
            authed_key = k
            authed_ws = ws
            break

    if not authed_key or not authed_ws:
        return _err("UNAUTHORIZED", "api_key is missing/invalid/revoked or workspace is not active")

    # Filter within workspace
    rows = []
    for r in search_queries:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") != authed_ws.get("id"):
            continue
        if status is not None and r.get("status") != status:
            continue
        if api_key_id is not None and r.get("api_key_id") != api_key_id:
            continue
        if tool_name is not None and r.get("tool_name") != tool_name:
            continue
        r_ca = _parse_dt(r.get("created_at"))
        if ca and r_ca and r_ca < ca:
            continue
        if cb and r_ca and r_ca >= cb:
            continue
        if (ca or cb) and (r_ca is None):
            continue
        rows.append(r)

    # Sort by created_at desc (unknowns last)
    def _sort_key(r):
        dt = _parse_dt(r.get("created_at"))
        if not dt:
            return (1, datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc))
        return (0, dt)
    rows.sort(key=_sort_key, reverse=True)

    total = len(rows)
    start = (page - 1) * per_page
    end = start + per_page
    page_rows = rows[start:end]
    has_more = end < total

    ts = datetime.datetime.now(datetime.timezone.utc).isoformat()
    authed_key["last_used_at"] = ts
    authed_key["updated_at"] = ts
    _save("api_keys.json", api_keys)

    return {
        "data": page_rows,
        "meta": {
            "page": page,
            "per_page": per_page,
            "total": total,
            "has_more": has_more,
            "duration_ms": int((time.time() - _t0) * 1000),
        },
    }

def get_search_query(api_key, id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0452000" if __import__("os").path.isdir("./environment_mix/0452000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if not isinstance(dt, datetime.datetime):
            dt = _now()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            # handle Z
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    def _gen_id(prefix, existing_ids):
        # low collision offline id
        base = int(time.time() * 1000)
        cand = f"{prefix}{base}"
        i = 0
        while cand in existing_ids:
            i += 1
            cand = f"{prefix}{base}_{i}"
        return cand

    # Plan defaults (not specified in schema; choose reasonable service-like defaults)
    def _plan_default_quota(plan):
        return {
            "free": 1000,
            "pro": 10000,
            "business": 100000,
            "enterprise": None,  # unlimited
        }.get(plan, 1000)

    def _month_window(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        start = dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
        # next month
        if start.month == 12:
            next_start = start.replace(year=start.year + 1, month=1)
        else:
            next_start = start.replace(month=start.month + 1)
        return start, next_start

    def _quota_for(ws, key):
        # monthly_request_quota_override if set else workspace.monthly_request_quota if set else plan default
        if isinstance(key, dict) and key.get("monthly_request_quota_override") is not None:
            return key.get("monthly_request_quota_override")
        if isinstance(ws, dict) and ws.get("monthly_request_quota") is not None:
            return ws.get("monthly_request_quota")
        return _plan_default_quota(ws.get("plan") if isinstance(ws, dict) else None)

    def _purge_old_for_workspace(workspace_id):
        # Best-effort retention enforcement for this workspace only.
        workspaces = _load("workspaces.json")
        if not isinstance(workspaces, list):
            workspaces = []
        ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
        if not ws:
            return
        rdays = ws.get("data_retention_days")
        if not isinstance(rdays, int) or rdays < 0:
            return
        cutoff = _now() - datetime.timedelta(days=rdays)

        queries = _load("search_queries.json")
        responses = _load("search_responses.json")
        ledger = _load("usage_ledger.json")
        if not isinstance(queries, list):
            queries = []
        if not isinstance(responses, list):
            responses = []
        if not isinstance(ledger, list):
            ledger = []

        # Purge responses older than retention: set purged and null payloads.
        changed_responses = False
        for rsp in responses:
            qid = rsp.get("query_id")
            # find query for workspace and created_at
            qrow = next((q for q in queries if q.get("id") == qid), None)
            if not qrow or qrow.get("workspace_id") != workspace_id:
                continue
            q_created = _parse_dt(qrow.get("created_at"))
            if q_created and q_created < cutoff and rsp.get("status") != "purged":
                rsp["status"] = "purged"
                rsp["response_json"] = None
                rsp["response_text"] = None
                rsp["updated_at"] = _iso(_now())
                changed_responses = True

        # Drop old query + ledger rows (allowed by "may be purged")
        changed_queries = False
        kept_queries = []
        purged_query_ids = set()
        for q in queries:
            if q.get("workspace_id") != workspace_id:
                kept_queries.append(q)
                continue
            q_created = _parse_dt(q.get("created_at"))
            if q_created and q_created < cutoff:
                purged_query_ids.add(q.get("id"))
                changed_queries = True
            else:
                kept_queries.append(q)

        changed_ledger = False
        kept_ledger = []
        for e in ledger:
            if e.get("workspace_id") != workspace_id:
                kept_ledger.append(e)
                continue
            e_created = _parse_dt(e.get("created_at")) or _parse_dt(e.get("occurred_at"))
            if e_created and e_created < cutoff:
                changed_ledger = True
                continue
            kept_ledger.append(e)

        # Also remove responses whose query was removed (cascade)
        if purged_query_ids:
            new_responses = []
            removed = False
            for rsp in responses:
                if rsp.get("query_id") in purged_query_ids:
                    removed = True
                    continue
                new_responses.append(rsp)
            if removed:
                responses = new_responses
                changed_responses = True

        if changed_queries:
            _save("search_queries.json", kept_queries)
        if changed_responses:
            _save("search_responses.json", responses)
        if changed_ledger:
            _save("usage_ledger.json", kept_ledger)

    def _resolve_auth(api_key_value, tool_name):
        # Authenticate against api_keys.id (client-visible id) primarily.
        keys = _load("api_keys.json")
        workspaces = _load("workspaces.json")
        if not isinstance(keys, list):
            keys = []
        if not isinstance(workspaces, list):
            workspaces = []

        # direct match by id (also allow matching key_hash if caller provided that, but never require it)
        candidates = []
        for k in keys:
            if k.get("id") == api_key_value or k.get("key_hash") == api_key_value:
                candidates.append(k)

        # If not found, no auth.
        for k in candidates:
            if k.get("status") != "active":
                continue
            if not isinstance(k.get("allowed_tools"), list) or tool_name not in k.get("allowed_tools"):
                continue
            ws = next((w for w in workspaces if w.get("id") == k.get("workspace_id")), None)
            if not ws:
                continue
            if ws.get("status") != "active":
                continue
            return ws, k
        return None, None

    def _enforce_rate_and_quota(ws, key):
        # Quota: count search_request events in current calendar month for this key (and workspace).
        ledger = _load("usage_ledger.json")
        if not isinstance(ledger, list):
            ledger = []
        now = _now()
        start, end = _month_window(now)
        count = 0
        for e in ledger:
            if e.get("workspace_id") != ws.get("id"):
                continue
            if e.get("api_key_id") != key.get("id"):
                continue
            if e.get("event_type") != "search_request":
                continue
            dt = _parse_dt(e.get("occurred_at")) or _parse_dt(e.get("created_at"))
            if not dt:
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            if start <= dt < end:
                count += 1

        quota = _quota_for(ws, key)
        if quota is not None and isinstance(quota, int) and count >= quota:
            return "QUOTA_EXCEEDED", f"Monthly request quota exceeded for this API key (limit={quota})."

        # Simple rate limit derived from ledger: max 5 search_request events in last 1 second.
        # (Schema doesn't define; implement observable dynamics consistent with stored sample 'rate_limited')
        one_sec_ago = now - datetime.timedelta(seconds=1)
        recent = 0
        for e in ledger:
            if e.get("workspace_id") != ws.get("id"):
                continue
            if e.get("api_key_id") != key.get("id"):
                continue
            if e.get("event_type") != "search_request":
                continue
            dt = _parse_dt(e.get("occurred_at")) or _parse_dt(e.get("created_at"))
            if not dt:
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            if dt >= one_sec_ago:
                recent += 1
        if recent >= 5:
            return "RATE_LIMIT", "Too many requests; please retry after 1s."
        return None, None

    def _log_call(ws_id, key_id, http_status, status, error_code=None, error_message=None, query_id=None):
        # Must record every call. usage_ledger is the only request-ish log in schema;
        # use 0-units non-billable entries, and keep event_type within enum via search_request with units=0.
        ledger = _load("usage_ledger.json")
        if not isinstance(ledger, list):
            ledger = []
        existing_ids = {r.get("id") for r in ledger if isinstance(r, dict)}
        ts = _iso(_now())
        entry = {
            "id": _gen_id("kgi_use_", existing_ids),
            "workspace_id": ws_id if isinstance(ws_id, str) else "unknown",
            "api_key_id": key_id if isinstance(key_id, str) else "unknown",
            "query_id": query_id if isinstance(query_id, str) else None,
            "event_type": "search_request",
            "units": 0,
            "occurred_at": ts,
            "created_at": ts,
            "updated_at": ts,
            "_endpoint": "get_search_query",
            "_http_status": http_status,
            "_status": status,
        }
        if error_code:
            entry["_error_code"] = error_code
        if error_message:
            entry["_error_message"] = error_message
        ledger.append(entry)
        _save("usage_ledger.json", ledger)

    # ---- validate inputs ----
    if not isinstance(api_key, str) or not api_key.strip():
        _log_call("unknown", "unknown", 401, "error", "auth_failed", "api_key is missing or invalid")
        return _err("UNAUTHORIZED", "api_key is missing or invalid")
    if not isinstance(id, str) or not id.strip():
        # log without a resolved principal
        _log_call("unknown", "unknown", 400, "error", "invalid_request", "id must be a non-empty string")
        return _err("VALIDATION_ERROR", "id must be a non-empty string")

    # ---- auth ----
    ws, key = _resolve_auth(api_key.strip(), "search")
    if not ws or not key:
        _log_call("unknown", "unknown", 401, "error", "auth_failed", "No active API key/workspace combination found for this request")
        return _err("UNAUTHORIZED", "api_key is missing/invalid/revoked or workspace is not active")

    # retention purging (best-effort) before serving
    _purge_old_for_workspace(ws.get("id"))

    # update last_used_at for successful authentication
    keys = _load("api_keys.json")
    if not isinstance(keys, list):
        keys = []
    now_iso = _iso(_now())
    changed = False
    for k in keys:
        if k.get("id") == key.get("id"):
            if k.get("last_used_at") != now_iso:
                k["last_used_at"] = now_iso
                k["updated_at"] = now_iso
                changed = True
            break
    if changed:
        _save("api_keys.json", keys)

    # quota/rate limit enforcement for reads too (observable)
    lim_code, lim_msg = _enforce_rate_and_quota(ws, key)
    if lim_code == "RATE_LIMIT":
        _log_call(ws.get("id"), key.get("id"), 429, "error", "rate_limited", lim_msg)
        return _err("RATE_LIMIT", lim_msg)
    if lim_code == "QUOTA_EXCEEDED":
        _log_call(ws.get("id"), key.get("id"), 429, "error", "quota_exceeded", lim_msg)
        return _err("QUOTA_EXCEEDED", lim_msg)

    # ---- fetch query by id within workspace ----
    queries = _load("search_queries.json")
    if not isinstance(queries, list):
        queries = []
    row = next((q for q in queries if q.get("id") == id and q.get("workspace_id") == ws.get("id")), None)
    if not row:
        _log_call(ws.get("id"), key.get("id"), 404, "error", "invalid_request", "Search query not found in workspace", query_id=id)
        return _err("NOT_FOUND", "Search query id does not exist in this workspace")

    latency_ms = int((time.time() - _t0) * 1000)
    _log_call(ws.get("id"), key.get("id"), 200, "ok", query_id=row.get("id"))
    return {
        "data": row,
        "meta": {
            "workspace_id": ws.get("id"),
            "api_key_id": key.get("id"),
            "latency_ms": latency_ms,
        },
    }

def get_search_response(api_key, query_id, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0452000" if __import__("os").path.isdir("./environment_mix/0452000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(endpoint, api_key_id, workspace_id, status, http_status, query_id=None, error_code=None, error_message=None, started_at=None):
        usage = _load("usage_ledger.json")
        ts = _now_iso()
        started = started_at if isinstance(started_at, float) else time.time()
        duration_ms = int(max(0, (time.time() - started) * 1000))

        # request-log-style ledger row (non-billable) to satisfy "every call records itself"
        rid = "ule_" + uuid.uuid4().hex
        usage.append({
            "id": rid,
            "workspace_id": workspace_id if workspace_id is not None else "unknown",
            "api_key_id": api_key_id if api_key_id is not None else "unknown",
            "query_id": query_id,
            "event_type": "search_failure" if status != "ok" else "search_success",
            "units": 0,
            "occurred_at": ts,
            "created_at": ts,
            "updated_at": ts,
            "endpoint": endpoint,
            "http_status": http_status,
            "duration_ms": duration_ms,
            "error_code": error_code,
            "error_message": error_message
        })
        _save("usage_ledger.json", usage)

    started = time.time()

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        _log("get_search_response", None, None, "error", 400, query_id=query_id if isinstance(query_id, str) else None,
             error_code="invalid_request", error_message="api_key must be a non-empty string", started_at=started)
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(query_id, str) or not query_id.strip():
        _log("get_search_response", None, None, "error", 400,
             error_code="invalid_request", error_message="query_id must be a non-empty string", started_at=started)
        return _err("VALIDATION_ERROR", "query_id must be a non-empty string")

    # Authenticate: match api_key parameter against api_keys.id OR api_keys.key_hash (client-visible value in this datastore)
    keys = _load("api_keys.json")
    workspaces = _load("workspaces.json")

    authed_key = None
    authed_ws = None
    for k in keys:
        if not isinstance(k, dict):
            continue
        if k.get("status") != "active":
            continue
        if api_key != k.get("id") and api_key != k.get("key_hash"):
            continue
        ws_id = k.get("workspace_id")
        ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == ws_id), None)
        if ws is None:
            continue
        if ws.get("status") != "active":
            continue
        authed_key = k
        authed_ws = ws
        break

    if authed_key is None or authed_ws is None:
        _log("get_search_response", None, None, "error", 401, query_id=query_id,
             error_code="auth_failed", error_message="Invalid or revoked API key, or workspace not active", started_at=started)
        return _err("UNAUTHORIZED", "Invalid or revoked API key, or workspace not active")

    # Update last_used_at
    now = _now_iso()
    mutated = False
    for k in keys:
        if isinstance(k, dict) and k.get("id") == authed_key.get("id"):
            k["last_used_at"] = now
            k["updated_at"] = now
            mutated = True
            break
    if mutated:
        _save("api_keys.json", keys)

    # Locate query and response scoped to workspace
    queries = _load("search_queries.json")
    qrow = next((q for q in queries if isinstance(q, dict) and q.get("id") == query_id and q.get("workspace_id") == authed_ws.get("id")), None)
    if qrow is None:
        _log("get_search_response", authed_key.get("id"), authed_ws.get("id"), "error", 404, query_id=query_id,
             error_code="invalid_request", error_message="Query not found in workspace", started_at=started)
        return _err("NOT_FOUND", "Query not found")

    responses = _load("search_responses.json")
    rrow = next((r for r in responses if isinstance(r, dict) and r.get("query_id") == query_id), None)
    # unique(query_id) => at most one. If none: NOT_FOUND
    if rrow is None:
        _log("get_search_response", authed_key.get("id"), authed_ws.get("id"), "error", 404, query_id=query_id,
             error_code="invalid_request", error_message="No response exists for this query", started_at=started)
        return _err("NOT_FOUND", "No response exists for this query")

    # Data retention enforcement (best-effort purge if too old)
    retention_days = authed_ws.get("data_retention_days")
    if isinstance(retention_days, int) and retention_days >= 0:
        created = _parse_dt(qrow.get("created_at"))
        if created is not None:
            cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(days=retention_days)
            if created < cutoff:
                # purge response payload if exists and not already purged
                if rrow.get("status") != "purged":
                    for rr in responses:
                        if isinstance(rr, dict) and rr.get("id") == rrow.get("id"):
                            rr["status"] = "purged"
                            rr["response_json"] = None
                            rr["response_text"] = None
                            rr["updated_at"] = now
                            rrow = rr
                            break
                    _save("search_responses.json", responses)

    # Build response envelope
    out = {
        "data": {
            "id": rrow.get("id"),
            "query_id": rrow.get("query_id"),
            "status": rrow.get("status"),
            "upstream_provider": rrow.get("upstream_provider"),
            "result_count": rrow.get("result_count"),
            "response_json": rrow.get("response_json"),
            "response_text": rrow.get("response_text"),
            "bytes": rrow.get("bytes"),
            "created_at": rrow.get("created_at"),
            "updated_at": rrow.get("updated_at"),
        }
    }

    _log("get_search_response", authed_key.get("id"), authed_ws.get("id"), "ok", 200, query_id=query_id, started_at=started)
    return out

def list_usage_ledger(api_key, page=None, per_page=None, event_type=None, api_key_id=None, query_id=None, occurred_after=None, occurred_before=None, **_extra):
