        per_page = 100

    if not isinstance(api_key, str) or not api_key.strip():
        _log("list_usage_ledger", None, None, "error", 400, "invalid_request", "api_key must be a non-empty string", started_at=started)
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")

    if not isinstance(page, int) or page < 1:
        _log("list_usage_ledger", None, None, "error", 400, "invalid_request", "page must be an integer >= 1", started_at=started)
        return _err("VALIDATION_ERROR", "page must be an integer >= 1")
    if not isinstance(per_page, int) or per_page < 1 or per_page > 200:
        _log("list_usage_ledger", None, None, "error", 400, "invalid_request", "per_page must be an integer between 1 and 200", started_at=started)
        return _err("VALIDATION_ERROR", "per_page must be an integer between 1 and 200")

    if event_type is not None:
        if not isinstance(event_type, str) or event_type not in ("search_request", "search_success", "search_failure"):
            _log("list_usage_ledger", None, None, "error", 400, "invalid_request", "event_type is invalid", started_at=started)
            return _err("VALIDATION_ERROR", "event_type is invalid")

    if api_key_id is not None and (not isinstance(api_key_id, str) or not api_key_id.strip()):
        _log("list_usage_ledger", None, None, "error", 400, "invalid_request", "api_key_id must be a non-empty string", started_at=started)
        return _err("VALIDATION_ERROR", "api_key_id must be a non-empty string")
    if query_id is not None and (not isinstance(query_id, str) or not query_id.strip()):
        _log("list_usage_ledger", None, None, "error", 400, "invalid_request", "query_id must be a non-empty string", started_at=started)
        return _err("VALIDATION_ERROR", "query_id must be a non-empty string")

    after_dt = _parse_dt(occurred_after) if occurred_after is not None else None
    if occurred_after is not None and after_dt is None:
        _log("list_usage_ledger", None, None, "error", 400, "invalid_request", "occurred_after must be RFC3339 date-time", started_at=started)
        return _err("VALIDATION_ERROR", "occurred_after must be RFC3339 date-time")
    before_dt = _parse_dt(occurred_before) if occurred_before is not None else None
    if occurred_before is not None and before_dt is None:
        _log("list_usage_ledger", None, None, "error", 400, "invalid_request", "occurred_before must be RFC3339 date-time", started_at=started)
        return _err("VALIDATION_ERROR", "occurred_before must be RFC3339 date-time")
    if after_dt is not None and before_dt is not None and after_dt > before_dt:
        _log("list_usage_ledger", None, None, "error", 400, "invalid_request", "occurred_after must be <= occurred_before", started_at=started)
        return _err("VALIDATION_ERROR", "occurred_after must be <= occurred_before")

    # Authenticate
    keys = _load("api_keys.json")
    workspaces = _load("workspaces.json")
    authed_key = None
    authed_ws = None
    for k in keys:
        if not isinstance(k, dict):
            continue
        if k.get("status") != "active":
            continue
        if api_key != k.get("id") and api_key != k.get("key_hash"):
            continue
        ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == k.get("workspace_id")), None)
        if ws is None or ws.get("status") != "active":
            continue
        authed_key = k
        authed_ws = ws
        break

    if authed_key is None:
        _log("list_usage_ledger", None, None, "error", 401, "auth_failed", "Invalid or revoked API key, or workspace not active", started_at=started)
        return _err("UNAUTHORIZED", "Invalid or revoked API key, or workspace not active")

    # Validate api_key_id filter belongs to workspace (if provided)
    if api_key_id is not None:
        krow = next((k for k in keys if isinstance(k, dict) and k.get("id") == api_key_id), None)
        if krow is None or krow.get("workspace_id") != authed_ws.get("id"):
            _log("list_usage_ledger", authed_key.get("id"), authed_ws.get("id"), "error", 404, "invalid_request", "api_key_id not found in workspace", started_at=started)
            return _err("NOT_FOUND", "api_key_id not found in workspace")

    # Update last_used_at
    now = _now_iso()
    for k in keys:
        if isinstance(k, dict) and k.get("id") == authed_key.get("id"):
            k["last_used_at"] = now
            k["updated_at"] = now
            break
    _save("api_keys.json", keys)

    ledger = _load("usage_ledger.json")

    # Data retention enforcement (best-effort purge old usage rows for workspace)
    retention_days = authed_ws.get("data_retention_days")
    if isinstance(retention_days, int) and retention_days >= 0:
        cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(days=retention_days)
        new_ledger = []
        changed = False
        for ev in ledger:
            if not isinstance(ev, dict):
                continue
            if ev.get("workspace_id") != authed_ws.get("id"):
                new_ledger.append(ev)
                continue
            odt = _parse_dt(ev.get("occurred_at")) or _parse_dt(ev.get("created_at"))
            if odt is not None and odt < cutoff:
                changed = True
                continue
            new_ledger.append(ev)
        if changed:
            ledger = new_ledger
            _save("usage_ledger.json", ledger)

    # Filter to workspace
    rows = [ev for ev in ledger if isinstance(ev, dict) and ev.get("workspace_id") == authed_ws.get("id")]

    if event_type is not None:
        rows = [ev for ev in rows if ev.get("event_type") == event_type]
    if api_key_id is not None:
        rows = [ev for ev in rows if ev.get("api_key_id") == api_key_id]
    if query_id is not None:
        rows = [ev for ev in rows if ev.get("query_id") == query_id]
    if after_dt is not None:
        def _ok_after(ev):
            dt = _parse_dt(ev.get("occurred_at"))
            return dt is not None and dt >= after_dt
        rows = [ev for ev in rows if _ok_after(ev)]
    if before_dt is not None:
        def _ok_before(ev):
            dt = _parse_dt(ev.get("occurred_at"))
            return dt is not None and dt < before_dt
        rows = [ev for ev in rows if _ok_before(ev)]

    # Sort by occurred_at desc
    def _sort_key(ev):
        dt = _parse_dt(ev.get("occurred_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        return dt
    rows.sort(key=_sort_key, reverse=True)

    total = len(rows)
    start_i = (page - 1) * per_page
    end_i = start_i + per_page
    page_rows = rows[start_i:end_i]
    has_more = end_i < total

    # Log call after preparing output
    _log("list_usage_ledger", authed_key.get("id"), authed_ws.get("id"), "ok", 200, started_at=started)

    return {
        "data": page_rows,
        "meta": {
            "page": page,
            "per_page": per_page,
            "total": total,
            "has_more": has_more
        }
    }

def update_search_response_status(api_key, id, status, redaction_reason=None, purge_now=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0452000" if __import__("os").path.isdir("./environment_mix/0452000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if not isinstance(dt, datetime.datetime):
            dt = _now()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    def _gen_id(prefix, existing_ids):
        base = int(time.time() * 1000)
        cand = f"{prefix}{base}"
        i = 0
        while cand in existing_ids:
            i += 1
            cand = f"{prefix}{base}_{i}"
        return cand

    def _plan_default_quota(plan):
        return {
            "free": 1000,
            "pro": 10000,
            "business": 100000,
            "enterprise": None,
        }.get(plan, 1000)

    def _month_window(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        start = dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
        if start.month == 12:
            next_start = start.replace(year=start.year + 1, month=1)
        else:
            next_start = start.replace(month=start.month + 1)
        return start, next_start

    def _quota_for(ws, key):
        if isinstance(key, dict) and key.get("monthly_request_quota_override") is not None:
            return key.get("monthly_request_quota_override")
        if isinstance(ws, dict) and ws.get("monthly_request_quota") is not None:
            return ws.get("monthly_request_quota")
        return _plan_default_quota(ws.get("plan") if isinstance(ws, dict) else None)

    def _resolve_auth(api_key_value, tool_name):
        keys = _load("api_keys.json")
        workspaces = _load("workspaces.json")
        if not isinstance(keys, list):
            keys = []
        if not isinstance(workspaces, list):
            workspaces = []

        candidates = []
        for k in keys:
            if k.get("id") == api_key_value or k.get("key_hash") == api_key_value:
                candidates.append(k)

        for k in candidates:
            if k.get("status") != "active":
                continue
            if not isinstance(k.get("allowed_tools"), list) or tool_name not in k.get("allowed_tools"):
                continue
            ws = next((w for w in workspaces if w.get("id") == k.get("workspace_id")), None)
            if not ws:
                continue
            if ws.get("status") != "active":
                continue
            return ws, k
        return None, None

    def _enforce_rate_and_quota(ws, key):
        ledger = _load("usage_ledger.json")
        if not isinstance(ledger, list):
            ledger = []
        now = _now()
        start, end = _month_window(now)
        count = 0
        for e in ledger:
            if e.get("workspace_id") != ws.get("id"):
                continue
            if e.get("api_key_id") != key.get("id"):
                continue
            if e.get("event_type") != "search_request":
                continue
            dt = _parse_dt(e.get("occurred_at")) or _parse_dt(e.get("created_at"))
            if not dt:
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            if start <= dt < end:
                count += 1

        quota = _quota_for(ws, key)
        if quota is not None and isinstance(quota, int) and count >= quota:
            return "QUOTA_EXCEEDED", f"Monthly request quota exceeded for this API key (limit={quota})."

        one_sec_ago = now - datetime.timedelta(seconds=1)
        recent = 0
        for e in ledger:
            if e.get("workspace_id") != ws.get("id"):
                continue
            if e.get("api_key_id") != key.get("id"):
                continue
            if e.get("event_type") != "search_request":
                continue
            dt = _parse_dt(e.get("occurred_at")) or _parse_dt(e.get("created_at"))
            if not dt:
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            if dt >= one_sec_ago:
                recent += 1
        if recent >= 5:
            return "RATE_LIMIT", "Too many requests; please retry after 1s."
        return None, None

    def _log_call(ws_id, key_id, http_status, status_txt, error_code=None, error_message=None, query_id=None):
        ledger = _load("usage_ledger.json")
        if not isinstance(ledger, list):
            ledger = []
        existing_ids = {r.get("id") for r in ledger if isinstance(r, dict)}
        ts = _iso(_now())
        entry = {
            "id": _gen_id("kgi_use_", existing_ids),
            "workspace_id": ws_id if isinstance(ws_id, str) else "unknown",
            "api_key_id": key_id if isinstance(key_id, str) else "unknown",
            "query_id": query_id if isinstance(query_id, str) else None,
            "event_type": "search_request",
            "units": 0,
            "occurred_at": ts,
            "created_at": ts,
            "updated_at": ts,
            "_endpoint": "update_search_response_status",
            "_http_status": http_status,
            "_status": status_txt,
        }
        if error_code:
            entry["_error_code"] = error_code
        if error_message:
            entry["_error_message"] = error_message
        ledger.append(entry)
        _save("usage_ledger.json", ledger)

    def _allowed_transition(cur, target):
        transitions = {
            "stored": {"redacted", "purged"},
            "redacted": {"purged"},
            "purged": set(),
        }
        return target in transitions.get(cur, set())

    # ---- validate inputs ----
    if not isinstance(api_key, str) or not api_key.strip():
        _log_call("unknown", "unknown", 401, "error", "auth_failed", "api_key is missing or invalid")
        return _err("UNAUTHORIZED", "api_key is missing or invalid")
    if not isinstance(id, str) or not id.strip():
        _log_call("unknown", "unknown", 400, "error", "invalid_request", "id must be a non-empty string")
        return _err("VALIDATION_ERROR", "id must be a non-empty string")
    if status not in ("redacted", "purged"):
        _log_call("unknown", "unknown", 400, "error", "invalid_request", "status must be one of: redacted, purged")
        return _err("VALIDATION_ERROR", "status must be one of: redacted, purged")
    if redaction_reason is not None and not isinstance(redaction_reason, str):
        _log_call("unknown", "unknown", 400, "error", "invalid_request", "redaction_reason must be a string if provided")
        return _err("VALIDATION_ERROR", "redaction_reason must be a string if provided")
    if purge_now is not None and not isinstance(purge_now, bool):
        _log_call("unknown", "unknown", 400, "error", "invalid_request", "purge_now must be a boolean if provided")
        return _err("VALIDATION_ERROR", "purge_now must be a boolean if provided")

    # ---- auth ----
    ws, key = _resolve_auth(api_key.strip(), "search")
    if not ws or not key:
        _log_call("unknown", "unknown", 401, "error", "auth_failed", "No active API key/workspace combination found for this request")
        return _err("UNAUTHORIZED", "api_key is missing/invalid/revoked or workspace is not active")

    # rate/quota enforcement
    lim_code, lim_msg = _enforce_rate_and_quota(ws, key)
    if lim_code == "RATE_LIMIT":
        _log_call(ws.get("id"), key.get("id"), 429, "error", "rate_limited", lim_msg)
        return _err("RATE_LIMIT", lim_msg)
    if lim_code == "QUOTA_EXCEEDED":
        _log_call(ws.get("id"), key.get("id"), 429, "error", "quota_exceeded", lim_msg)
        return _err("QUOTA_EXCEEDED", lim_msg)

    # update last_used_at for successful authentication
    keys = _load("api_keys.json")
    if not isinstance(keys, list):
        keys = []
    now_iso = _iso(_now())
    changed_key = False
    for k in keys:
        if k.get("id") == key.get("id"):
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            changed_key = True
            break
    if changed_key:
        _save("api_keys.json", keys)

    # ---- find response by id scoped to workspace ----
    responses = _load("search_responses.json")
    queries = _load("search_queries.json")
    if not isinstance(responses, list):
        responses = []
    if not isinstance(queries, list):
        queries = []

    rsp = next((r for r in responses if r.get("id") == id), None)
    if not rsp:
        _log_call(ws.get("id"), key.get("id"), 404, "error", "invalid_request", "Search response not found", query_id=None)
        return _err("NOT_FOUND", "Search response id does not exist in this workspace")

    qid = rsp.get("query_id")
    qrow = next((q for q in queries if q.get("id") == qid), None)
    if not qrow or qrow.get("workspace_id") != ws.get("id"):
        _log_call(ws.get("id"), key.get("id"), 404, "error", "invalid_request", "Search response not found in workspace", query_id=qid if isinstance(qid, str) else None)
        return _err("NOT_FOUND", "Search response id does not exist in this workspace")

    current_status = rsp.get("status")
    if current_status == status:
        # idempotent success (no changes required)
        latency_ms = int((time.time() - _t0) * 1000)
        _log_call(ws.get("id"), key.get("id"), 200, "ok", query_id=qid)
        return {
            "data": rsp,
            "meta": {
                "workspace_id": ws.get("id"),
                "api_key_id": key.get("id"),
                "idempotent": True,
                "latency_ms": latency_ms,
            },
        }

    if not _allowed_transition(current_status, status):
        _log_call(ws.get("id"), key.get("id"), 409, "error", "invalid_request", f"Illegal transition {current_status} → {status}", query_id=qid)
        return _err("INVALID_TRANSITION", f"Illegal search_responses.status transition: {current_status} → {status}")

    # ---- apply transition ----
    ts = _iso(_now())
    rsp["status"] = status
    rsp["updated_at"] = ts

    # record reason in non-schema metadata (schema doesn't include it, but tool accepts)
    if redaction_reason is not None:
        rsp["_redaction_reason"] = redaction_reason

    if status == "purged":
        # if purge_now is false, backend may schedule; but tool supports immediate purge; we implement:
        # - if purge_now is True or omitted, purge immediately.
        do_purge = True if purge_now is None else bool(purge_now)
        if do_purge:
            rsp["response_json"] = None
            rsp["response_text"] = None
            # bytes could remain or be nulled; keep but allow client to see old; better to null.
            rsp["bytes"] = None

    # persist mutation
    _save("search_responses.json", responses)

    latency_ms = int((time.time() - _t0) * 1000)
    _log_call(ws.get("id"), key.get("id"), 200, "ok", query_id=qid)
    return {
        "data": rsp,
        "meta": {
            "workspace_id": ws.get("id"),
            "api_key_id": key.get("id"),
            "latency_ms": latency_ms,
        },
    }
